        align-items: center;
        justify-content: center;
        z-index: 9999;
        transition: all 0.3s ease-in-out;
        }

        .ad-popup-box {
        position: relative;
        max-width: 450px;
        width: 85%;
        background: #fff;
        padding: 8px; 
        border-radius: 15px; 
        transform: scale(0.7); 
        transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .ad-popup-overlay.active {
        display: flex;
        }
        .ad-popup-overlay.active .ad-popup-box {
        transform: scale(1);
        }

        .ad-image-wrapper {
        position: relative;
        overflow: hidden;
        border-radius: 10px;
        }

        .ad-popup-box img {
        width: 100%;
        height: auto;
        display: block;
        transition: transform 0.5s ease;
        }

