        .ad-popup-close {
        position: absolute;
        top: -15px;
        right: -15px;
        background: #ff4757; 
        color: #fff;
        border: 3px solid #fff;
        width: 36px;
        height: 36px;
        font-size: 22px;
        font-weight: bold;
        cursor: pointer;
        border-radius: 50%;
        box-shadow: 0 4px 10px rgba(0,0,0,0.3);
